// Railway infrastructure as code for lapline.live. It replaces railway.json,
// which Railway stops reading on 1 December 2026.
//
// Railway does not read this file at deploy time. After a change to it is
// merged, someone signed in to the Railway CLI applies it by hand:
//
//   railway config plan     # read it first
//   railway config apply
//
// A dashboard change to a setting this file declares is undone by the next
// apply, so change the file instead. Generated by `railway config migrate`,
// with the restart policy added back from railway.json.
//
// `railway/iac` comes from the `railway` package, a dev dependency that only
// the CLI uses to evaluate this file; the app never imports it, and nothing
// type-checks this file.
import { defineRailway, github, project, service } from 'railway/iac';

// This repository manages only its own resources in the environment.
// See https://docs.railway.com/infrastructure-as-code#multi-repo-projects
export const partial = 'lapline';

export default defineRailway(() => {
  const lapline = service('lapline', {
    // Deploys main, and only once every GitHub Actions run on the commit has
    // passed (Railway's "Wait for CI").
    source: github('sara-selvaraju/lapline', { branch: 'main', checkSuites: true }),
    build: { buildCommand: 'npm run build', buildEnvironment: 'V3', builder: 'NIXPACKS' },
    start: 'npm start',
    // A new deploy goes live only once /healthz answers, so a broken build
    // never replaces the running version.
    healthcheck: '/healthz',
    healthcheckTimeout: 120,
    // The server exits on an uncaught exception (apps/server/src/index.ts)
    // and comes back clean.
    deploy: { restartPolicyType: 'ON_FAILURE', restartPolicyMaxRetries: 10 },
    // Exactly one: session, clock and buffers live in memory, and one server
    // spends the OpenF1 rate limit for every viewer.
    replicas: { 'us-west2': 1 },
    // Both stay listed, the apex included, even while Railway shows it as
    // unverified: it is how requests for the apex reach the service.
    domains: ['lapline.live', 'www.lapline.live'],
  });

  return project('lapline', {
    // Variables (APP_PASSWORD, SESSION_SECRET, the OpenF1 login) are set in
    // the Railway dashboard, never here.
    variables: { managed: false },
    resources: [lapline],
  });
});
